INSERT INTO `course_details` VALUES (1,1,'Introduction to Database Systems','Understanding data, information, and database concepts. Overview of file-based systems and their limitations.',2.00,0.50,1,'2026-09-05 11:47:53','2026-09-05 11:47:53'),(2,1,'Database Architecture & Data Models','Three-level database architecture, data abstraction, data independence, ER model, and relational model overview.',3.00,1.00,2,'2026-09-05 11:47:53','2026-09-05 11:47:53'),(3,1,'Entity Relationship (ER) Modeling','ER diagrams, entities, attributes, relationships, keys, cardinality, and conversion to relational schema.',2.50,1.50,3,'2026-09-05 11:47:53','2026-09-05 11:47:53'),(4,1,'Relational Algebra and Calculus','Operations like select, project, join, union, difference, and division. Introduction to tuple and domain relational calculus.',3.00,1.00,4,'2026-09-05 11:47:53','2026-09-05 11:47:53'),(5,1,'SQL – Structured Query Language','DDL, DML, DCL, TCL commands; constraints; joins; nested queries; aggregate functions; and views.',4.00,4.00,5,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(6,1,'Normalization and Functional Dependencies','Concepts of normalization, 1NF to 5NF, BCNF, and identifying anomalies and dependencies.',3.00,1.00,6,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(7,1,'Transaction Management and Concurrency Control','ACID properties, transaction states, serializability, locking, and deadlock handling.',3.00,1.00,7,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(8,1,'Database Recovery and Backup Techniques','Recovery techniques, checkpoints, log-based recovery, and backup strategies.',2.00,0.50,8,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(9,1,'Database Security and Authorization','User authentication, privileges, roles, encryption, and SQL injection prevention.',2.00,0.50,9,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(10,1,'PL/SQL and Stored Procedures','Procedural extensions in SQL: variables, cursors, loops, triggers, and stored procedures.',2.50,2.50,10,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(11,1,'Indexing and Query Optimization','B-trees, hashing, cost-based optimization, and use of indexes for performance tuning.',2.00,1.00,11,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(12,1,'NoSQL Overview (Optional)','Brief comparison between relational and NoSQL databases, document and key-value stores.',1.50,0.50,12,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(13,2,'Introduction to Advanced Java','Overview of Core vs Advanced Java, JDK structure, and setup for development with IDEs.',1.50,0.50,1,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(14,2,'Java Database Connectivity (JDBC)','JDBC architecture, connection interface, statements, prepared statements, result sets, and transactions.',3.00,3.00,2,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(15,2,'Servlets and Web Applications','Servlet lifecycle, request/response handling, session management, cookies, and deployment in Tomcat.',3.00,4.00,3,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(16,2,'JavaServer Pages (JSP)','JSP lifecycle, implicit objects, directives, JSTL, and JSP-Servlet integration.',2.50,3.00,4,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(17,2,'JavaBeans and Custom Tags','Creating reusable components using JavaBeans and using custom tag libraries in JSP.',2.00,2.00,5,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(18,2,'Java Networking','Working with sockets, URL and InetAddress classes, client-server communication, and multithreading with sockets.',2.50,2.50,6,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(19,2,'Remote Method Invocation (RMI)','Distributed programming with RMI: remote interfaces, stubs, skeletons, and registry.',2.00,2.00,7,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(20,2,'Java Message Service (JMS)','Messaging concepts, point-to-point vs publish-subscribe models, and message-driven beans.',2.50,1.50,8,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(21,2,'Spring Framework Basics','Introduction to IoC, dependency injection, and using annotations in Spring Core.',3.00,3.00,9,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(22,2,'Hibernate ORM Framework','Object-relational mapping, configuration, session management, CRUD operations, and relationships.',3.00,3.00,10,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(23,2,'Spring MVC Architecture','Model-View-Controller architecture, form handling, validation, and integration with Hibernate.',3.00,3.00,11,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(24,2,'RESTful Web Services in Java','Creating REST APIs using Spring Boot, JSON handling, and HTTP methods.',2.50,3.00,12,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(25,2,'Java Security and Authentication','User authentication, encryption, SSL, and secure coding practices in Java applications.',2.00,1.50,13,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(26,2,'Project Work','Building a full-stack Java web application integrating Servlets, JSP, JDBC, and Spring Boot.',1.00,6.00,14,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(27,3,'Introduction to Accounting and Tally Prime','Overview of accounting principles, need for computerised accounting, introduction to Tally Prime interface and features.',1.50,1.00,1,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(28,3,'Company Creation and Configuration','Creating, selecting, altering and deleting companies; managing data directories; security and user management.',1.00,2.00,2,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(29,3,'Fundamentals of Accounting in Tally','Understanding Groups, Ledgers, Vouchers, and Double Entry System; creating and managing ledger accounts.',1.50,2.50,3,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(30,3,'Voucher Entries','Recording transactions using different voucher types — Payment, Receipt, Contra, Journal, Sales, and Purchase.',2.00,3.00,4,'2026-09-05 11:47:54','2026-09-05 11:47:54'),(31,3,'Inventory Management in Tally Prime','Stock groups, stock categories, stock items, units of measure, and stock valuation methods.',2.00,3.00,5,'2026-09-05 11:47:54','