INSERT INTO `questions` VALUES (1,'What is Python?',NULL,NULL,1,1,1,'[\"python\", \"introduction\", \"basics\"]','[\"class_8\", \"class_9\", \"class_10\", \"all\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(2,'Who developed the Python programming language?',NULL,NULL,1,1,1,'[\"python\", \"history\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(3,'In which year was Python first released?',NULL,NULL,1,1,1,'[\"python\", \"history\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(4,'Python is which type of programming language?',NULL,NULL,1,1,1,'[\"python\", \"features\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(5,'Which of the following is a key feature of Python?',NULL,NULL,1,1,1,'[\"python\", \"features\"]','[\"class_8\", \"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(6,'Python is mainly used for which of the following?',NULL,NULL,1,1,1,'[\"python\", \"uses\"]','[\"class_8\", \"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(7,'Which company uses Python extensively?',NULL,NULL,1,1,1,'[\"python\", \"industry\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(8,'Python is best suited for beginners because:',NULL,NULL,1,1,1,'[\"python\", \"beginners\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(9,'Which domain uses Python for data analysis?',NULL,NULL,1,1,1,'[\"python\", \"data-science\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(10,'Python can be used for Artificial Intelligence?',NULL,NULL,1,1,1,'[\"python\", \"ai\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(11,'Python supports which programming style?',NULL,NULL,1,1,1,'[\"python\", \"paradigm\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(12,'Which of the following is NOT a use of Python?',NULL,NULL,1,1,1,'[\"python\", \"uses\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(13,'Python is an open-source language. What does it mean?',NULL,NULL,1,1,1,'[\"python\", \"open-source\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(14,'Which field uses Python for automation?',NULL,NULL,1,1,1,'[\"python\", \"automation\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(15,'Python is platform independent. What does it mean?',NULL,NULL,1,1,1,'[\"python\", \"platform\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(16,'Which library is commonly used in Python for machine learning?',NULL,NULL,1,1,1,'[\"python\", \"ml\"]','[\"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(17,'Python is widely used in which sector?',NULL,NULL,1,1,1,'[\"python\", \"industry\"]','[\"class_8\", \"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(18,'Python is commonly used for which of the following?',NULL,NULL,1,1,1,'[\"python\", \"applications\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(19,'Why is Python popular today?',NULL,NULL,1,1,1,'[\"python\", \"popularity\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(20,'Which of the following best describes Python?',NULL,NULL,1,1,1,'[\"python\", \"basics\", \"definition\"]','[\"class_8\", \"class_9\", \"class_10\", \"all\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(21,'Python is known for which type of syntax?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"syntax\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(22,'Python is an interpreted language. What does this mean?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"interpreted\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(23,'Which feature of Python helps it run on different operating systems?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"platform-independent\"]','[\"class_8\", \"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(24,'Python supports which programming paradigm?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"paradigm\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(25,'Which feature allows Python to have a large collection of libraries?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"libraries\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(26,'Python is dynamically typed. What does it mean?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"dynamic-typing\"]','[\"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(27,'Which feature of Python makes debugging easier?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"debugging\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(28,'Python manages memory automatically. Which feature enables this?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"memory\"]','[\"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(29,'Which feature makes Python suitable for rapid application development?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"development\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(30,'Which feature of Python helps beginners learn programming easily?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"beginner-friendly\"]','[\"class_8\", \"class_9\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(31,'Which feature of Python allows code reuse?',NULL,NULL,1,2,1,'[\"python\", \"features\", \"reusability\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(32,'Python programs are easy to maintain because of:',NULL,NULL,1,2,1,'[\"python\", \"features\", \"maintenance\"]','[\"class_9\", \"class_10\"]',1,'2026-09-05 11:47:55','2026-09-05 11:47:55'),(33,'Which feature allows Python to be exte